:root {
  --bg: #1b1f3b;
  --card: #252a52;
  --ink: #f4f4ff;
  --muted: #b7b9e0;
  --accent: #7c5cff;
  --accent-strong: #9b82ff;
  --good: #38d39f;
  --danger: #ff6b81;
  --track: #3a3f70;
  --radius: 14px;
}

* { box-sizing: border-box; }

[hidden] { display: none !important; }

html, body { margin: 0; padding: 0; }

body {
  min-height: 100vh;
  background:
    radial-gradient(circle at 20% 0%, #2a2f63 0%, transparent 55%),
    radial-gradient(circle at 100% 100%, #3b2a63 0%, transparent 50%),
    var(--bg);
  color: var(--ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  padding: 24px 16px 48px;
}

.app {
  max-width: 640px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.app-header { text-align: center; margin-bottom: 4px; }

h1 {
  font-size: clamp(1.5rem, 5vw, 2rem);
  margin: 0 0 6px;
  letter-spacing: 0.5px;
}

.subtitle { margin: 0; color: var(--muted); font-size: 1rem; }

.card {
  background: var(--card);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35);
}

h2 { margin: 0 0 14px; font-size: 1.15rem; }

.add-form { display: flex; flex-direction: column; gap: 14px; }

.field { display: flex; flex-direction: column; gap: 6px; }

label { font-size: 0.95rem; color: var(--muted); }

input {
  width: 100%;
  font: inherit;
  font-size: 1rem;
  padding: 11px 12px;
  color: var(--ink);
  background: #1f2347;
  border: 1px solid #434a86;
  border-radius: 10px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

input::placeholder { color: #8a8fc4; }

input:hover { border-color: var(--accent-strong); }

input:focus-visible {
  outline: none;
  border-color: var(--accent-strong);
  box-shadow: 0 0 0 3px rgba(124, 92, 255, 0.4);
}

.btn {
  font: inherit;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  border-radius: 10px;
  border: 1px solid transparent;
  padding: 11px 16px;
  transition: transform 0.08s ease, background-color 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
}

.btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(124, 92, 255, 0.5);
}

.btn:active { transform: translateY(1px); }

.btn-primary { background: var(--accent); color: #fff; }
.btn-primary:hover { background: var(--accent-strong); }

.btn-ghost {
  background: transparent;
  color: var(--ink);
  border-color: #434a86;
}
.btn-ghost:hover { border-color: var(--accent-strong); background: rgba(124, 92, 255, 0.12); }

.error {
  margin: 12px 0 0;
  color: var(--danger);
  font-size: 0.95rem;
}

.empty { color: var(--muted); margin: 0; }

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.book {
  background: #1f2347;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 12px;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.book-top {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px 12px;
}

.book-title {
  font-weight: 700;
  font-size: 1.05rem;
  overflow-wrap: anywhere;
}

.book-meta { color: var(--muted); font-size: 0.9rem; white-space: nowrap; }

.badge {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 700;
  padding: 2px 9px;
  border-radius: 999px;
  background: rgba(56, 211, 159, 0.15);
  color: var(--good);
  border: 1px solid rgba(56, 211, 159, 0.4);
}

.progress-wrap { display: flex; flex-direction: column; gap: 6px; }

.progress {
  height: 14px;
  background: var(--track);
  border-radius: 999px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, var(--accent), var(--accent-strong));
  border-radius: 999px;
  transition: width 0.25s ease;
}

.book.finished .progress-fill { background: linear-gradient(90deg, #2bb98a, var(--good)); }

.progress-labels {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 0.9rem;
  color: var(--muted);
}

.percent { font-weight: 700; color: var(--ink); }

.log-form {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.log-form label { flex-basis: 100%; }

.log-form input { width: 96px; }

@media (min-width: 480px) {
  .add-form { flex-direction: row; align-items: flex-end; }
  .field { flex: 1 1 0; }
  .add-form .btn { flex: 0 0 auto; }
}

(function () {
  'use strict';

  var books = [];
  var nextId = 1;

  var addForm = document.getElementById('add-form');
  var titleInput = document.getElementById('title-input');
  var pagesInput = document.getElementById('pages-input');
  var formError = document.getElementById('form-error');
  var bookList = document.getElementById('book-list');
  var emptyState = document.getElementById('empty-state');

  function clamp(n, min, max) {
    return Math.min(max, Math.max(min, n));
  }

  function percentOf(book) {
    if (book.pageCount <= 0) return 0;
    return clamp(Math.round((book.pagesRead / book.pageCount) * 100), 0, 100);
  }

  function isFinished(book) {
    return book.pagesRead >= book.pageCount;
  }

  function showError(message) {
    formError.textContent = message;
    formError.hidden = !message;
  }

  function addBook(title, pageCount) {
    books.push({
      id: nextId++,
      title: title,
      pageCount: pageCount,
      pagesRead: 0
    });
  }

  function logPages(id, amount) {
    var book = books.find(function (b) { return b.id === id; });
    if (!book) return;
    book.pagesRead = clamp(book.pagesRead + amount, 0, book.pageCount);
  }

  function render() {
    bookList.innerHTML = '';
    emptyState.hidden = books.length > 0;

    books.forEach(function (book) {
      var pct = percentOf(book);
      var finished = isFinished(book);

      var li = document.createElement('li');
      li.className = 'book' + (finished ? ' finished' : '');
      li.dataset.id = String(book.id);

      var top = document.createElement('div');
      top.className = 'book-top';

      var title = document.createElement('span');
      title.className = 'book-title';
      title.textContent = book.title;

      var meta = document.createElement('span');
      meta.className = 'book-meta';
      meta.textContent = book.pagesRead + ' / ' + book.pageCount + ' pages';

      top.appendChild(title);
      top.appendChild(meta);
      if (finished) {
        var badge = document.createElement('span');
        badge.className = 'badge';
        badge.textContent = 'Finished';
        top.appendChild(badge);
      }

      var wrap = document.createElement('div');
      wrap.className = 'progress-wrap';

      var bar = document.createElement('div');
      bar.className = 'progress';
      bar.setAttribute('role', 'progressbar');
      bar.setAttribute('aria-label', 'Progress for ' + book.title);
      bar.setAttribute('aria-valuemin', '0');
      bar.setAttribute('aria-valuemax', '100');
      bar.setAttribute('aria-valuenow', String(pct));
      bar.setAttribute('aria-valuetext', pct + '% complete');

      var fill = document.createElement('div');
      fill.className = 'progress-fill';
      fill.style.width = pct + '%';
      bar.appendChild(fill);

      var labels = document.createElement('div');
      labels.className = 'progress-labels';

      var percent = document.createElement('span');
      percent.className = 'percent';
      percent.textContent = pct + '%';

      var status = document.createElement('span');
      status.textContent = finished ? 'Complete' : (book.pageCount - book.pagesRead) + ' pages left';

      labels.appendChild(percent);
      labels.appendChild(status);

      wrap.appendChild(bar);
      wrap.appendChild(labels);

      var logForm = document.createElement('form');
      logForm.className = 'log-form';
      logForm.setAttribute('novalidate', '');

      var inputId = 'log-' + book.id;
      var logLabel = document.createElement('label');
      logLabel.setAttribute('for', inputId);
      logLabel.textContent = 'Pages read now';

      var logInput = document.createElement('input');
      logInput.type = 'number';
      logInput.id = inputId;
      logInput.min = '1';
      logInput.step = '1';
      logInput.inputMode = 'numeric';
      logInput.value = '1';
      logInput.setAttribute('aria-label', 'Pages to log for ' + book.title);

      var logBtn = document.createElement('button');
      logBtn.type = 'submit';
      logBtn.className = 'btn btn-ghost';
      logBtn.textContent = 'Log pages';
      logBtn.disabled = finished;
      if (finished) {
        logBtn.setAttribute('aria-disabled', 'true');
      }

      logForm.appendChild(logLabel);
      logForm.appendChild(logInput);
      logForm.appendChild(logBtn);

      logForm.addEventListener('submit', function (event) {
        event.preventDefault();
        var amount = parseInt(logInput.value, 10);
        if (isNaN(amount) || amount <= 0) {
          logInput.focus();
          return;
        }
        logPages(book.id, amount);
        render();
      });

      li.appendChild(top);
      li.appendChild(wrap);
      li.appendChild(logForm);
      bookList.appendChild(li);
    });
  }

  addForm.addEventListener('submit', function (event) {
    event.preventDefault();
    var title = titleInput.value.trim();
    var pageCount = parseInt(pagesInput.value, 10);

    if (!title) {
      showError('Please enter a book title.');
      titleInput.focus();
      return;
    }
    if (isNaN(pageCount) || pageCount < 1) {
      showError('Page count must be a whole number of at least 1.');
      pagesInput.focus();
      return;
    }

    showError('');
    addBook(title, pageCount);
    addForm.reset();
    render();
    titleInput.focus();
  });

  render();
})();
